package com.bank.talentreview;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class AboveAvgDemo {
    private static final Logger log = Logger.getLogger("TalentReview");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000),  // IT avg 800k → above
            new Employee("Amit", "IT", 600000),
            new Employee("Priya", "Sales", 950000),  // Sales avg 725k → above
            new Employee("Neha", "Sales", 500000));
        TalentReviewService service = new TalentReviewService();

        log.info(() -> "Above own-dept average: " + service.aboveOwnDeptAverage(staff));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalaryAsDouble() { return salary; }
}

// ─── Would be in service/TalentReviewService.java ───
class TalentReviewService {
    List<String> aboveOwnDeptAverage(List<Employee> staff) {
        Map<String, Double> avgByDept = staff.stream()
            .collect(groupingBy(Employee::getDepartment,
                averagingDouble(Employee::getSalaryAsDouble)));          // pass 1
        return staff.stream()
            .filter(e -> e.getSalaryAsDouble() > avgByDept.get(e.getDepartment())) // pass 2
            .map(Employee::getName)
            .toList();
    }
}
